+const MAX_SESSION_ID_LENGTH = 128;
+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const {limit, before} = message;
+  if (limit !== undefined && !(typeof limit === 'number' && Number.isInteger(limit) && limit >= 0)) {
+    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+  }
+  const data: ListSessionsMessage = {type: 'list_sessions', ...(limit === undefined ? {} : {limit})};
+  if (before === undefined) return {valid: true, data};
+
+  const cursor = validateCursor(before);
+  if (typeof cursor === 'string') return {valid: false, error: cursor};
+  return {valid: true, data: {...data, before: cursor}};
+}
+
+// The cursor a client sends back: the last row it saw, after JSON, so a string or an epoch number.
+function validateCursor(before: unknown): SessionCursor | string {
+  if (typeof before !== 'object' || before === null) return 'list_sessions before must be an object';
+  const {sessionId, updatedAt} = before as Record<string, unknown>;
+  if (typeof sessionId !== 'string' || sessionId.length === 0 || sessionId.length > MAX_SESSION_ID_LENGTH) {
+    return `list_sessions before.sessionId must be a string of 1-${MAX_SESSION_ID_LENGTH} characters`;
+  }
+  if (!isTimestamp(updatedAt)) return 'list_sessions before.updatedAt must be a valid timestamp';
+  return {updatedAt, sessionId};
+}
+
+function isTimestamp(value: unknown): value is string | number {
+  if (typeof value === 'number') return Number.isFinite(value);
+  return typeof value === 'string' && Number.isFinite(Date.parse(value));
+}
